762: async function navigateJourneyStage(action){const context=currentProductionWorkingContext();if(action==='scope'||!context){setAppRoute('production');openProductionScopeDialog();return}if(action==='character-review'){setAppRoute('character-review');await loadCharacterReview();return}if(action==='confirm-casting'||action==='casting-ready'){setAppRoute('production');await loadProductionTaskProjection({silent:true});requestAnimationFrame(()=>($('#productionPrimaryAction')||$('#productionCurrentWorkArea h2'))?.focus?.({preventScroll:true}));return}setAppRoute('assignment');await loadBookVoiceRegistry({force:false});if(action==='review')focusAssignmentReviewQueue();else if(action==='voices')openAssignmentVoiceSection()}
